 18	void AmbientOcclusionPass::ASSAOConstants::SetPass(int32 passIndex)
 19	{
 20	    PassIndex = passIndex;
 21	    PerPassFullResCoordOffsetX = passIndex % 2;
 22	    PerPassFullResCoordOffsetY = passIndex / 2;
 23	    const int32 subPassCount = 5;
 24	    const float spmap[5]{ 0.0f, 1.0f, 4.0f, 3.0f, 2.0f };
 25	    const float a = static_cast<float>(passIndex);
 26	
 27	    for (int32 subPass = 0; subPass < subPassCount; subPass++)
 28	    {
 29	        const float b = spmap[subPass];
 30	
 31	        const float angle0 = (a + b / subPassCount) * PI * 0.5f;
 32	        const float ca = Math::Cos(angle0);
 33	        const float sa = Math::Sin(angle0);
 34	
 35	        const float scale = 1.0f + (a - 1.5f + (b - (subPassCount - 1.0f) * 0.5f) / static_cast<float>(subPassCount)) * 0.07f;
 36	        PatternRotScaleMatrices[subPass] = Float4(scale * ca, scale * -sa, -scale * sa, -scale * ca);
 37	    }
 38	}
