 82	            Float3 L = 2 * Float3::Dot(V, H) * H - V;
 83	
 84	            float NoL = Math::Saturate(L.Z);
 85	            float NoH = Math::Saturate(H.Z);
 86	            float VoH = Math::Saturate(Float3::Dot(V, H));
