 65	void TAA::Render(const RenderContext& renderContext, GPUTexture* input, GPUTextureView* output)
 66	{
 67	    auto context = GPUDevice::Instance->GetMainContext();
 68	
 69	    // Ensure to have valid data
 70	    if (checkIfSkipPass())
 71	    {
 72	        // Resources are missing. Do not perform rendering, just copy source frame.
 73	        context->SetRenderTarget(output);
 74	        context->Draw(input);
 75	        return;
 76	    }
 77	    const auto& settings = renderContext.List->Settings.AntiAliasing;
 78	
 79	    PROFILE_GPU_CPU("Temporal Antialiasing");
 80	
 81	    // Get history buffers
 82	    bool resetHistory = renderContext.Task->IsCameraCut;
 83	    renderContext.Buffers->LastFrameTemporalAA = Engine::FrameCount;
 84	    const auto tempDesc = GPUTextureDescription::New2D(input->Width(), input->Height(), input->Format());
 85	    if (renderContext.Buffers->TemporalAA == nullptr)
 86	    {
 87	        // Missing temporal buffer
 88	        renderContext.Buffers->TemporalAA = RenderTargetPool::Get(tempDesc);
 89	        RENDER_TARGET_POOL_SET_NAME(renderContext.Buffers->TemporalAA, "TemporalAA");
 90	        resetHistory = true;
 91	    }
 92	    else if (renderContext.Buffers->TemporalAA->Width() != tempDesc.Width || renderContext.Buffers->TemporalAA->Height() != tempDesc.Height)
 93	    {
 94	        // Wrong size temporal buffer
 95	        RenderTargetPool::Release(renderContext.Buffers->TemporalAA);
 96	        renderContext.Buffers->TemporalAA = RenderTargetPool::Get(tempDesc);
 97	        RENDER_TARGET_POOL_SET_NAME(renderContext.Buffers->TemporalAA, "TemporalAA");
 98	        resetHistory = true;
 99	    }
100	    auto inputHistory = renderContext.Buffers->TemporalAA;
101	    const auto outputHistory = RenderTargetPool::Get(tempDesc);
102	    RENDER_TARGET_POOL_SET_NAME(outputHistory, "TemporalAA");
103	
104	    // Duplicate the current frame to the history buffer if need to reset the temporal history
105	    float blendStrength = 1.0f;
106	    if (resetHistory)
107	    {
108	#if 0
109	        context->CopyTexture(inputHistory, 0, 0, 0, 0, input, 0);
110	#else
111	        context->SetRenderTarget(inputHistory->View());
112	        context->Draw(input);
113	        context->ResetRenderTarget();
114	#endif
115	        blendStrength = 0.0f;
116	    }
117	
118	    // Bind input
119	    Data data;
120	    data.ScreenSizeInv.X = renderContext.View.ScreenSize.Z;
121	    data.ScreenSizeInv.Y = renderContext.View.ScreenSize.W;
122	    data.JitterInv.X = renderContext.View.TemporalAAJitter.X / (float)tempDesc.Width;
123	    data.JitterInv.Y = renderContext.View.TemporalAAJitter.Y / (float)tempDesc.Height;
124	    data.Sharpness = settings.TAA_Sharpness;
125	    data.StationaryBlending = settings.TAA_StationaryBlending * blendStrength;
126	    data.MotionBlending = settings.TAA_MotionBlending * blendStrength;
127	    data.QuantizationError = RenderTools::GetColorQuantizationError(tempDesc.Format);
128	    GBufferPass::SetInputs(renderContext.View, data.GBuffer);
129	    const auto cb = _shader->GetShader()->GetCB(0);
130	    context->UpdateCB(cb, &data);
131	    context->BindCB(0, cb);
132	    context->BindSR(0, input);
133	    context->BindSR(1, inputHistory);
134	    context->BindSR(2, renderContext.Buffers->MotionVectors);
135	    context->BindSR(3, renderContext.Buffers->DepthBuffer);
136	
137	    // Render
138	    context->SetRenderTarget(output);
139	    context->SetState(_psTAA);
140	    context->DrawFullscreenTriangle();
141	
142	    // Update the history
143	    {
144	        RenderTargetPool::Release(inputHistory);
145	        context->ResetRenderTarget();
146	        context->SetRenderTarget(outputHistory->View());
147	        context->Draw(output);
148	        renderContext.Buffers->TemporalAA = outputHistory;
149	    }
150	
151	    // Mark TAA jitter as resolved for future drawing
152	    (bool&)renderContext.View.IsTaaResolved = true;
153	}
