 19	void AmbientOcclusionPass::ASSAOConstants::SetPass(int32 passIndex)
 20	{
 21	    PassIndex = passIndex;
 22	    PerPassFullResCoordOffsetX = passIndex % 2;
 23	    PerPassFullResCoordOffsetY = passIndex / 2;
 24	    const int32 subPassCount = 5;
 25	    const float spmap[5]{ 0.0f, 1.0f, 4.0f, 3.0f, 2.0f };
 26	    const float a = static_cast<float>(passIndex);
 27	
 28	    for (int32 subPass = 0; subPass < subPassCount; subPass++)
 29	    {
 30	        const float b = spmap[subPass];
 31	
 32	        const float angle0 = (a + b / subPassCount) * PI * 0.5f;
 33	        const float ca = Math::Cos(angle0);
 34	        const float sa = Math::Sin(angle0);
 35	
 36	        const float scale = 1.0f + (a - 1.5f + (b - (subPassCount - 1.0f) * 0.5f) / static_cast<float>(subPassCount)) * 0.07f;
 37	        PatternRotScaleMatrices[subPass] = Float4(scale * ca, scale * -sa, -scale * sa, -scale * ca);
 38	    }
 39	}
