116	bool AmbientOcclusionPass::setupResources()
117	{
118	    // Check shader
119	    if (!_shader->IsLoaded())
120	        return true;
121	    const auto shader = _shader->GetShader();
122	    CHECK_INVALID_SHADER_PASS_CB_SIZE(shader, 0, ASSAOConstants);
123	
124	    // Create pipeline states
125	    auto psDesc = GPUPipelineState::Description::DefaultFullscreenTriangle;
126	    psDesc.BlendMode.RenderTargetWriteMask = BlendingMode::ColorWrite::Red;
127	    if (!_psPrepareDepths->IsValid())
128	    {
129	        psDesc.PS = shader->GetPS("PS_PrepareDepths");
130	        if (_psPrepareDepths->Init(psDesc))
131	            return true;
132	    }
133	    if (!_psPrepareDepthsHalf->IsValid())
134	    {
135	        psDesc.PS = shader->GetPS("PS_PrepareDepthsHalf");
136	        if (_psPrepareDepthsHalf->Init(psDesc))
137	            return true;
138	    }
139	    for (int32 i = 0; i < ARRAY_COUNT(_psPrepareDepthMip); i++)
140	    {
141	        if (!_psPrepareDepthMip[i]->IsValid())
142	        {
143	            const auto str = String::Format(TEXT("PS_PrepareDepthMip{0}"), i + 1);
144	            const StringAsANSI<50> strAnsi(*str, str.Length());
145	            psDesc.PS = shader->GetPS(strAnsi.Get());
146	            if (_psPrepareDepthMip[i]->Init(psDesc))
147	                return true;
148	        }
149	    }
150	    psDesc.BlendMode.RenderTargetWriteMask = BlendingMode::ColorWrite::RG;
151	    for (int32 i = 0; i < ARRAY_COUNT(_psGenerate); i++)
152	    {
153	        if (!_psGenerate[i]->IsValid())
154	        {
155	            const auto str = String::Format(TEXT("PS_GenerateQ{0}"), i);
156	            const StringAsANSI<50> strAnsi(*str, str.Length());
157	            psDesc.PS = shader->GetPS(strAnsi.Get());
158	            if (_psGenerate[i]->Init(psDesc))
159	                return true;
160	        }
161	    }
162	    if (!_psSmartBlur->IsValid())
163	    {
164	        psDesc.PS = shader->GetPS("PS_SmartBlur");
165	        if (_psSmartBlur->Init(psDesc))
166	            return true;
167	    }
168	    if (!_psSmartBlurWide->IsValid())
169	    {
170	        psDesc.PS = shader->GetPS("PS_SmartBlurWide");
171	        if (_psSmartBlurWide->Init(psDesc))
172	            return true;
173	    }
174	    if (!_psNonSmartBlur->IsValid())
175	    {
176	        psDesc.PS = shader->GetPS("PS_NonSmartBlur");
177	        if (_psNonSmartBlur->Init(psDesc))
178	            return true;
179	    }
180	    psDesc.BlendMode = BlendingMode::Multiply;
181	    psDesc.BlendMode.RenderTargetWriteMask = BlendingMode::ColorWrite::Alpha; // Write only into AO channel in GBuffer
182	    if (_depthBounds)
183	    {
184	        psDesc.DepthEnable = psDesc.DepthBoundsEnable = true;
185	        psDesc.DepthWriteEnable = false;
186	    }
187	    if (!_psApply->IsValid())
188	    {
189	        psDesc.PS = shader->GetPS("PS_Apply");
190	        if (_psApply->Init(psDesc))
191	            return true;
192	    }
193	    if (!_psApplyHalf->IsValid())
194	    {
195	        psDesc.PS = shader->GetPS("PS_ApplyHalf");
196	        if (_psApplyHalf->Init(psDesc))
197	            return true;
198	    }
199	
200	    return false;
201	}
