112	{
113	    // Dof
114	    if (_platformSupportsDoF == false)
115	        return false;
116	
117	    // Wait for shader
118	    if (!_shader->IsLoaded())
119	        return true;
120	    const auto shader = _shader->GetShader();
121	    CHECK_INVALID_SHADER_PASS_CB_SIZE(shader, 0, Data);
122	
123	    // Create pipeline stages
124	    GPUPipelineState::Description psDesc = GPUPipelineState::Description::DefaultFullscreenTriangle;
125	    if (!_psDofDepthBlurGeneration->IsValid())
126	    {
127	        psDesc.PS = shader->GetPS("PS_DofDepthBlurGeneration");
128	        if (_psDofDepthBlurGeneration->Init(psDesc))
129	            return true;
130	    }
131	    if (!_psDoNotGenerateBokeh->IsValid())
132	    {
133	        psDesc.PS = shader->GetPS("PS_DoNotGenerateBokeh");
134	        if (_psDoNotGenerateBokeh->Init(psDesc))
135	            return true;
136	    }
137	#if GPU_ALLOW_GEOMETRY_SHADERS
138	    if (_platformSupportsBokeh)
139	    {
140	        if (!_psBokehGeneration->IsValid())
141	        {
142	            psDesc.PS = shader->GetPS("PS_GenerateBokeh");
143	            if (_psBokehGeneration->Init(psDesc))
144	                return true;
145	        }
146	        if (!_psBokehComposite->IsValid())
147	        {
148	            psDesc.PS = shader->GetPS("PS_BokehComposite");
149	            if (_psBokehComposite->Init(psDesc))
150	                return true;
151	        }
152	        if (!_psBokeh->IsValid())
153	        {
154	            psDesc.VS = shader->GetVS("VS_Bokeh");
155	            psDesc.GS = shader->GetGS("GS_Bokeh");
156	            psDesc.PS = shader->GetPS("PS_Bokeh");
157	            psDesc.BlendMode = BlendingMode::Additive;
