149	void MotionBlurPass::RenderMotionVectors(RenderContext& renderContext)
150	{
151	    auto motionVectors = renderContext.Buffers->MotionVectors;
152	    ASSERT(motionVectors);
153	    MotionBlurSettings& settings = renderContext.List->Settings.MotionBlur;
154	    auto context = GPUDevice::Instance->GetMainContext();
155	    const int32 screenWidth = renderContext.Buffers->GetWidth();
156	    const int32 screenHeight = renderContext.Buffers->GetHeight();
157	    const int32 motionVectorsWidth = RenderTools::GetResolution(screenWidth, settings.MotionVectorsResolution);
158	    const int32 motionVectorsHeight = RenderTools::GetResolution(screenHeight, settings.MotionVectorsResolution);
159	    if (!renderContext.List->Setup.UseMotionVectors || checkIfSkipPass())
160	    {
161	        // Skip pass (just clear motion vectors if texture is allocated)
162	        if (motionVectors->IsAllocated())
163	        {
164	            if (motionVectors->Width() == motionVectorsWidth && motionVectors->Height() == motionVectorsHeight)
165	                context->Clear(motionVectors->View(), Color::Black);
166	            else
167	                motionVectors->ReleaseGPU();
168	        }
169	        return;
170	    }
171	
172	    PROFILE_GPU_CPU("Motion Vectors");
173	
174	    // Ensure to have valid motion vectors texture
175	    if (!motionVectors->IsAllocated() || motionVectors->Width() != motionVectorsWidth || motionVectors->Height() != motionVectorsHeight)
176	    {
177	        if (motionVectors->Init(GPUTextureDescription::New2D(motionVectorsWidth, motionVectorsHeight, _motionVectorsFormat, GPUTextureFlags::ShaderResource | GPUTextureFlags::RenderTarget)))
178	        {
179	            LOG(Warning, "Failed to create  motion vectors render target.");
180	            return;
181	        }
182	    }
183	
184	    // Prepare
185	    GPUTexture* depthBuffer;
186	    if (settings.MotionVectorsResolution != ResolutionMode::Full)
187	    {
188	        depthBuffer = renderContext.Buffers->RequestHalfResDepth(context);
189	        context->SetViewportAndScissors((float)motionVectorsWidth, (float)motionVectorsHeight);
190	    }
191	    else
192	    {
193	        depthBuffer = renderContext.Buffers->DepthBuffer;
194	    }
195	
196	    // Bind input
197	    Data data;
198	    GBufferPass::SetInputs(renderContext.View, data.GBuffer);
199	    Matrix::Transpose(renderContext.View.ViewProjection(), data.CurrentVP);
200	    Matrix::Transpose(renderContext.View.PrevViewProjection, data.PreviousVP);
201	    data.TemporalAAJitter = renderContext.View.TemporalAAJitter;
202	    data.PrevWorldOriginOffset = renderContext.View.Origin - renderContext.View.PrevOrigin;
203	    auto cb = _shader->GetShader()->GetCB(0);
204	    context->UpdateCB(cb, &data);
205	    context->BindCB(0, cb);
206	    context->BindSR(0, depthBuffer);
207	
208	    // Render camera motion vectors (background)
209	    if (!data.TemporalAAJitter.IsZero() || data.CurrentVP != data.PreviousVP)
210	    {
211	        PROFILE_GPU("Camera Motion Vectors");
212	        context->SetRenderTarget(motionVectors->View());
213	        context->SetState(_psCameraMotionVectors);
214	        context->DrawFullscreenTriangle();
215	    }
216	    else
217	    {
218	        // Simple clear if camera is not moving
219	        context->Clear(motionVectors->View(), Color::Black);
220	    }
221	
222	    // Render per-object motion vectors (use depth buffer to discard dynamic objects pixels covered by the static geometry)
223	    context->ResetSR();
224	    context->SetRenderTarget(depthBuffer->View(), motionVectors->View());
225	    renderContext.View.Pass = DrawPass::MotionVectors;
226	    // TODO: maybe update material PerFrame data because render viewport can be other size than ScreenSize from render buffers
227	    renderContext.List->ExecuteDrawCalls(renderContext, DrawCallsListType::MotionVectors);
228	
229	    // Cleanup
230	    context->ResetRenderTarget();
231	    if (settings.MotionVectorsResolution != ResolutionMode::Full)
232	    {
233	        const auto viewport = renderContext.Task->GetViewport();
234	        context->SetViewportAndScissors(viewport);
235	    }
236	}
