112	bool DepthOfFieldPass::setupResources()
113	{
114	    // Dof
115	    if (_platformSupportsDoF == false)
116	        return false;
117	
118	    // Wait for shader
119	    if (!_shader->IsLoaded())
120	        return true;
121	    const auto shader = _shader->GetShader();
122	    CHECK_INVALID_SHADER_PASS_CB_SIZE(shader, 0, Data);
123	
124	    // Create pipeline stages
125	    GPUPipelineState::Description psDesc = GPUPipelineState::Description::DefaultFullscreenTriangle;
126	    if (!_psDofDepthBlurGeneration->IsValid())
127	    {
128	        psDesc.PS = shader->GetPS("PS_DofDepthBlurGeneration");
129	        if (_psDofDepthBlurGeneration->Init(psDesc))
130	            return true;
131	    }
132	    if (!_psDoNotGenerateBokeh->IsValid())
133	    {
134	        psDesc.PS = shader->GetPS("PS_DoNotGenerateBokeh");
135	        if (_psDoNotGenerateBokeh->Init(psDesc))
136	            return true;
137	    }
138	#if GPU_ALLOW_GEOMETRY_SHADERS
139	    if (_platformSupportsBokeh)
140	    {
141	        if (!_psBokehGeneration->IsValid())
142	        {
143	            psDesc.PS = shader->GetPS("PS_GenerateBokeh");
144	            if (_psBokehGeneration->Init(psDesc))
145	                return true;
146	        }
147	        if (!_psBokehComposite->IsValid())
148	        {
149	            psDesc.PS = shader->GetPS("PS_BokehComposite");
150	            if (_psBokehComposite->Init(psDesc))
151	                return true;
152	        }
153	        if (!_psBokeh->IsValid())
154	        {
155	            psDesc.VS = shader->GetVS("VS_Bokeh");
156	            psDesc.GS = shader->GetGS("GS_Bokeh");
157	            psDesc.PS = shader->GetPS("PS_Bokeh");
158	            psDesc.BlendMode = BlendingMode::Additive;
159	            psDesc.PrimitiveTopology = PrimitiveTopologyType::Point;
160	            if (_psBokeh->Init(psDesc))
161	                return true;
162	        }
163	
164	        // Create buffer
165	        if (_bokehBuffer == nullptr)
166	            _bokehBuffer = GPUDevice::Instance->CreateBuffer(TEXT("Bokeh Buffer"));
167	        if (_bokehIndirectArgsBuffer == nullptr)
168	            _bokehIndirectArgsBuffer = GPUDevice::Instance->CreateBuffer(TEXT("Bokeh Indirect Args Buffer"));
169	        GPUDrawIndirectArgs indirectArgsBufferInitData{ 0, 1, 0, 0 };
170	        if (_bokehIndirectArgsBuffer->Init(GPUBufferDescription::Argument(&indirectArgsBufferInitData, sizeof(indirectArgsBufferInitData))))
171	            return true;
172	    }
173	#endif
174	
175	    return false;
176	}
