150	void MotionBlurPass::RenderMotionVectors(RenderContext& renderContext)
151	{
152	    auto motionVectors = renderContext.Buffers->MotionVectors;
153	    ASSERT(motionVectors);
154	    MotionBlurSettings& settings = renderContext.List->Settings.MotionBlur;
155	    auto context = GPUDevice::Instance->GetMainContext();
156	    const int32 screenWidth = renderContext.Buffers->GetWidth();
157	    const int32 screenHeight = renderContext.Buffers->GetHeight();
158	    const int32 motionVectorsWidth = RenderTools::GetResolution(screenWidth, settings.MotionVectorsResolution);
159	    const int32 motionVectorsHeight = RenderTools::GetResolution(screenHeight, settings.MotionVectorsResolution);
160	    if (!renderContext.List->Setup.UseMotionVectors || checkIfSkipPass())
161	    {
162	        // Skip pass (just clear motion vectors if texture is allocated)
163	        if (motionVectors->IsAllocated())
164	        {
165	            if (motionVectors->Width() == motionVectorsWidth && motionVectors->Height() == motionVectorsHeight)
166	                context->Clear(motionVectors->View(), Color::Black);
167	            else
168	                motionVectors->ReleaseGPU();
169	        }
170	        return;
171	    }
172	
173	    PROFILE_GPU_CPU("Motion Vectors");
174	
175	    // Ensure to have valid motion vectors texture
176	    if (!motionVectors->IsAllocated() || motionVectors->Width() != motionVectorsWidth || motionVectors->Height() != motionVectorsHeight)
177	    {
178	        if (motionVectors->Init(GPUTextureDescription::New2D(motionVectorsWidth, motionVectorsHeight, _motionVectorsFormat, GPUTextureFlags::ShaderResource | GPUTextureFlags::RenderTarget)))
179	        {
180	            LOG(Warning, "Failed to create  motion vectors render target.");
181	            return;
182	        }
183	    }
184	
185	    // Prepare
186	    GPUTexture* depthBuffer;
187	    if (settings.MotionVectorsResolution != ResolutionMode::Full)
188	    {
189	        depthBuffer = renderContext.Buffers->RequestHalfResDepth(context);
190	        context->SetViewportAndScissors((float)motionVectorsWidth, (float)motionVectorsHeight);
191	    }
192	    else
193	    {
194	        depthBuffer = renderContext.Buffers->DepthBuffer;
195	    }
196	
197	    // Bind input
198	    Data data;
199	    GBufferPass::SetInputs(renderContext.View, data.GBuffer);
200	    Matrix::Transpose(renderContext.View.ViewProjection(), data.CurrentVP);
201	    Matrix::Transpose(renderContext.View.PrevViewProjection, data.PreviousVP);
202	    data.TemporalAAJitter = renderContext.View.TemporalAAJitter;
203	    data.PrevWorldOriginOffset = renderContext.View.Origin - renderContext.View.PrevOrigin;
204	    auto cb = _shader->GetShader()->GetCB(0);
205	    context->UpdateCB(cb, &data);
206	    context->BindCB(0, cb);
207	    context->BindSR(0, depthBuffer);
208	
209	    // Render camera motion vectors (background)
210	    if (!data.TemporalAAJitter.IsZero() || data.CurrentVP != data.PreviousVP)
211	    {
212	        PROFILE_GPU("Camera Motion Vectors");
213	        context->SetRenderTarget(motionVectors->View());
214	        context->SetState(_psCameraMotionVectors);
215	        context->DrawFullscreenTriangle();
216	    }
217	    else
218	    {
219	        // Simple clear if camera is not moving
220	        context->Clear(motionVectors->View(), Color::Black);
221	    }
222	
223	    // Render per-object motion vectors (use depth buffer to discard dynamic objects pixels covered by the static geometry)
224	    context->ResetSR();
225	    context->SetRenderTarget(depthBuffer->View(), motionVectors->View());
226	    renderContext.View.Pass = DrawPass::MotionVectors;
227	    // TODO: maybe update material PerFrame data because render viewport can be other size than ScreenSize from render buffers
228	    renderContext.List->ExecuteDrawCalls(renderContext, DrawCallsListType::MotionVectors);
229	
230	    // Cleanup
231	    context->ResetRenderTarget();
232	    if (settings.MotionVectorsResolution != ResolutionMode::Full)
233	    {
234	        const auto viewport = renderContext.Task->GetViewport();
235	        context->SetViewportAndScissors(viewport);
236	    }
237	}
