174	/// <summary>
175	/// Calculates the Gaussian blur filter kernel. This implementation is
176	/// ported from the original Java code appearing in chapter 16 of
177	/// "Filthy Rich Clients: Developing Animated and Graphical Effects for Desktop Java".
178	/// </summary>
179	/// <param name="sigma">Gaussian Blur sigma parameter</param>
180	/// <param name="width">Texture to blur width in pixels</param>
181	/// <param name="height">Texture to blur height in pixels</param>
182	void GB_ComputeKernel(float sigma, float width, float height, Float4 gaussianBlurCacheH[GB_KERNEL_SIZE], Float4 gaussianBlurCacheV[GB_KERNEL_SIZE])
183	{
184	    float total = 0.0f;
185	    float twoSigmaSquare = 2.0f * sigma * sigma;
186	    float sigmaRoot = Math::Sqrt(twoSigmaSquare * PI);
187	    float xOffset = 1.0f / width;
188	    float yOffset = 1.0f / height;
189	
190	    // Calculate weights and offsets
191	    for (int32 i = -GB_RADIUS; i <= GB_RADIUS; i++)
192	    {
193	        // Calculate pixel distance and index
194	        const float distance = static_cast<float>(i * i);
195	        const int32 index = i + GB_RADIUS;
196	
197	        // Calculate pixel weight
198	        const float weight = Math::Exp(-distance / twoSigmaSquare) / sigmaRoot;
199	
200	        // Calculate total weights sum
201	        total += weight;
202	
203	        gaussianBlurCacheH[index] = Float4(weight, i * xOffset, 0, 0);
204	        gaussianBlurCacheV[index] = Float4(weight, i * yOffset, 0, 0);
205	    }
206	
207	    // Normalize weights
208	    for (int32 i = 0; i < GB_KERNEL_SIZE; i++)
209	    {
210	        gaussianBlurCacheH[i].X /= total;
211	        gaussianBlurCacheV[i].X /= total;
212	    }
213	}
