234	int32 CalculateBloomMipCount(int32 width, int32 height)
235	{
236	    // Calculate the smallest dimension
237	    int32 minDimension = Math::Min(width, height);
238	
239	    // Calculate how many times we can half the dimension until we hit a minimum size
240	    // (e.g., 16x16 pixels as the smallest mip)
241	    const int32 MIN_MIP_SIZE = 16;
242	    int32 mipCount = 1;
243	    while (minDimension > MIN_MIP_SIZE)
244	    {
245	        minDimension /= 2;
246	        mipCount++;
247	    }
248	    return mipCount;
249	}
