133	    }
134	    case EyeAdaptationMode::AutomaticAverageLuminance:
135	    {
136	        const Int2 luminanceMapSize(colorBuffer->Width() / 2, colorBuffer->Height() / 2);
137	        GPUTexture* luminanceMap = RenderTargetPool::Get(GPUTextureDescription::New2D(luminanceMapSize.X, luminanceMapSize.Y, 0, PixelFormat::R16_Float, GPUTextureFlags::ShaderResource | GPUTextureFlags::RenderTarget | GPUTextureFlags::PerMipViews));
