 64	void HistogramPass::GetHistogramMad(float& multiply, float& add)
 65	{
 66	    const float histogramLogMin = -8.0f;
 67	    const float histogramLogMax = 6.0f;
 68	    const float histogramLogRange = histogramLogMax - histogramLogMin;
 69	    multiply = 1.0f / histogramLogRange;
 70	    add = -histogramLogMin * multiply;
 71	}
