 176	        // Invalidate static chunks intersecting with dirty bounds
 177	        RasterizeChunkKey key;
 178	        key.Layer = 0;
 179	        for (key.Coord.Z = objectChunkMin.Z; key.Coord.Z <= objectChunkMax.Z; key.Coord.Z++)
 180	        {
 181	            for (key.Coord.Y = objectChunkMin.Y; key.Coord.Y <= objectChunkMax.Y; key.Coord.Y++)
 182	            {
 183	                for (key.Coord.X = objectChunkMin.X; key.Coord.X <= objectChunkMax.X; key.Coord.X++)
 184	                {
 185	                    key.Hash = key.Coord.Z * (RasterizeChunkKeyHashResolution * RasterizeChunkKeyHashResolution) + key.Coord.Y * RasterizeChunkKeyHashResolution + key.Coord.X;
 186	                    StaticChunks.Remove(key);
 187	                }
 188	            }
 189	        }
 190	    }
 191	};
