 52	class DownloadProbeTask : public ThreadPoolTask
 53	{
 54	private:
 55	    GPUTexture* _texture;
 56	    TextureData _data;
 57	    ProbeEntry _entry;
 58	
 59	public:
 60	    DownloadProbeTask(GPUTexture* target, const ProbeEntry& entry)
 61	        : _texture(target)
 62	        , _entry(entry)
 63	    {
 64	    }
 65	
 66	    FORCE_INLINE TextureData& GetData()
 67	    {
 68	        return _data;
 69	    }
 70	
 71	    bool Run() override
 72	    {
 73	        Actor* actor = _entry.Actor.Get();
 74	        if (_entry.Type == ProbeEntry::Types::EnvProbe)
 75	        {
 76	            if (actor)
 77	                ((EnvironmentProbe*)actor)->SetProbeData(_data);
 78	        }
 79	        else if (_entry.Type == ProbeEntry::Types::SkyLight)
 80	        {
 81	            if (actor)
 82	                ((SkyLight*)actor)->SetProbeData(_data);
 83	        }
 84	        else
 85	        {
 86	            return true;
 87	        }
 88	
 89	        ProbesRenderer::OnFinishBake(actor);
 90	        return false;
 91	    }
 92	};
