121	    CHECK_INVALID_SHADER_PASS_CB_SIZE(shader, 0, Data);
122	    // CB1 is used for per-draw info (ObjectIndex)
123	    CHECK_INVALID_SHADER_PASS_CB_SIZE(shader, 2, PerLight);
124	
125	    // Cache compute shaders
126	    _csInitialize = shader->GetCS("CS_Initialize");
127	    _csLightScattering.Get(shader, "CS_LightScattering");
128	    _csFinalIntegration = shader->GetCS("CS_FinalIntegration");
129	
130	    // Create pipeline stages
131	    GPUPipelineState::Description psDesc;
132	    if (!_psInjectLight.IsValid())
133	    {
134	        psDesc = GPUPipelineState::Description::DefaultFullscreenTriangle;
135	        psDesc.BlendMode = BlendingMode::Add;
136	        psDesc.VS = shader->GetVS("VS_WriteToSlice");
