  84	bool RenderLightData::CanRenderShadow(const RenderView& view) const
  85	{
  86	    bool result = false;
  87	    switch (ShadowsMode)
  88	    {
  89	    case ShadowsCastingMode::StaticOnly:
  90	        result = view.IsOfflinePass;
  91	        break;
  92	    case ShadowsCastingMode::DynamicOnly:
  93	        result = !view.IsOfflinePass;
  94	        break;
  95	    case ShadowsCastingMode::All:
  96	        result = true;
  97	        break;
  98	    }
  99	    return result && ShadowsStrength > ZeroTolerance;
 100	}
