 119	bool RenderLocalLightData::CanRenderShadow(const RenderView& view) const
 120	{
 121	    // Fade shadow on distance
 122	    const float fadeDistance = Math::Max(ShadowsFadeDistance, 0.1f);
 123	    const float dstLightToView = Float3::Distance(Position, view.Position);
 124	    const float fade = 1 - Math::Saturate((dstLightToView - Radius - ShadowsDistance + fadeDistance) / fadeDistance);
 125	    return fade > ZeroTolerance && Radius > 10 && RenderLightData::CanRenderShadow(view);
 126	}
