 51	{
 52	    Half4 lightmapUVsAreaPacked(*(Float4*)&lightmapUVsArea);
 53	    Float2 lightmapUVsAreaPackedAliased = *(Float2*)&lightmapUVsAreaPacked;
 54	    Raw[0] = Float4(worldMatrix.M11, worldMatrix.M12, worldMatrix.M13, worldMatrix.M41);
