633	FORCE_INLINE void CalculateSortKey(const RenderContext& renderContext, DrawCall& drawCall, int8 sortOrder)
634	{
635	    const Float3 planeNormal = renderContext.View.Direction;
636	    const float planePoint = -Float3::Dot(planeNormal, renderContext.View.Position);
637	    const float distance = Float3::Dot(planeNormal, drawCall.ObjectPosition) - planePoint;
638	    uint32 distanceKey = RenderTools::ComputeDistanceSortKey(distance);
639	    uint32 batchKey = GetHash(drawCall.Material);
640	    IMaterial::InstancingHandler handler;
641	    if (drawCall.Material->CanUseInstancing(handler))
642	        handler.GetHash(drawCall, batchKey);
643	    batchKey = (batchKey * 397) ^ drawCall.StencilValue;
644	    uint32 drawKey = (uint32)(471 * drawCall.WorldDeterminant);
645	    drawKey = (drawKey * 397) ^ GetHash(drawCall.Geometry.VertexBuffers[0]);
646	    drawKey = (drawKey * 397) ^ GetHash(drawCall.Geometry.VertexBuffers[1]);
647	    drawKey = (drawKey * 397) ^ GetHash(drawCall.Geometry.VertexBuffers[2]);
648	    drawKey = (drawKey * 397) ^ GetHash(drawCall.Geometry.IndexBuffer);
649	
650	    PackedSortKey key;
651	    key.BatchKey = (uint16)batchKey;
652	    key.DistanceKey = distanceKey;
653	    key.DrawKey = (uint8)drawKey;
654	    key.SortKey = (uint8)(sortOrder - MIN_int8);
655	    drawCall.SortKey = *(uint64*)&key;
656	}
