296	void RenderGraph::AllocateResources()
297	{
298	    if (!_resourceManager)
299	        return;
300	
301	    PROFILE_CPU_NAMED("RenderGraph.AllocateResources");
302	
303	    // Allocate textures
304	    for (int32 i = 0; i < _textures.Count(); i++)
305	    {
306	        TextureResource& resource = _textures[i];
307	
308	        // Skip imported resources (already have GPU texture)
309	        if (resource.IsImported)
310	            continue;
311	
312	        // Skip if already allocated
313	        if (resource.Texture)
314	            continue;
315	
316	        // Get lifetime information from compiler
317	        const auto& lifetime = _compiler->GetTextureLifetime(i);
318	        
319	        // Skip resources that are never used
320	        if (lifetime.FirstUse == -1 || lifetime.LastUse == -1)
321	            continue;
322	
323	        // Allocate texture from resource manager
324	        resource.Texture = _resourceManager->AllocateTexture(resource.Desc, lifetime);
325	    }
326	
327	    // Allocate buffers
328	    for (int32 i = 0; i < _buffers.Count(); i++)
329	    {
330	        BufferResource& resource = _buffers[i];
331	
332	        // Skip imported resources (already have GPU buffer)
333	        if (resource.IsImported)
334	            continue;
335	
336	        // Skip if already allocated
337	        if (resource.Buffer)
338	            continue;
339	
340	        // Get lifetime information from compiler
341	        const auto& lifetime = _compiler->GetBufferLifetime(i);
342	        
343	        // Skip resources that are never used
344	        if (lifetime.FirstUse == -1 || lifetime.LastUse == -1)
345	            continue;
346	
347	        // Allocate buffer from resource manager
348	        resource.Buffer = _resourceManager->AllocateBuffer(resource.Desc, lifetime);
349	    }
350	}
