 141	void RenderAntiAliasingPass(RenderContext& renderContext, GPUTexture* input, GPUTextureView* output, const Viewport& outputViewport)
 142	{
 143	    auto context = GPUDevice::Instance->GetMainContext();
 144	    const auto aaMode = renderContext.List->Settings.AntiAliasing.Mode;
 145	    if (ContrastAdaptiveSharpeningPass::Instance()->CanRender(renderContext))
 146	    {
 147	        if (aaMode == AntialiasingMode::FastApproximateAntialiasing ||
 148	            aaMode == AntialiasingMode::SubpixelMorphologicalAntialiasing)
 149	        {
 150	            // AA -> CAS -> Output
 151	            auto tmpImage = RenderTargetPool::Get(input->GetDescription());
 152	            RENDER_TARGET_POOL_SET_NAME(tmpImage, "TmpImage");
 153	            context->SetViewportAndScissors((float)tmpImage->Width(), (float)tmpImage->Height());
 154	            if (aaMode == AntialiasingMode::FastApproximateAntialiasing)
 155	                FXAA::Instance()->Render(renderContext, input, tmpImage->View());
 156	            else
 157	                SMAA::Instance()->Render(renderContext, input, tmpImage->View());
 158	            context->ResetSR();
 159	            context->ResetRenderTarget();
 160	            context->SetViewportAndScissors(outputViewport);
 161	            ContrastAdaptiveSharpeningPass::Instance()->Render(renderContext, tmpImage, output);
 162	            RenderTargetPool::Release(tmpImage);
 163	        }
 164	        else
 165	        {
 166	            // CAS -> Output
 167	            context->SetViewportAndScissors(outputViewport);
 168	            ContrastAdaptiveSharpeningPass::Instance()->Render(renderContext, input, output);
 169	        }
 170	    }
 171	    else
 172	    {
 173	        // AA -> Output
 174	        context->SetViewportAndScissors(outputViewport);
 175	        if (aaMode == AntialiasingMode::FastApproximateAntialiasing)
 176	            FXAA::Instance()->Render(renderContext, input, output);
 177	        else if (aaMode == AntialiasingMode::SubpixelMorphologicalAntialiasing)
 178	            SMAA::Instance()->Render(renderContext, input, output);
 179	        else
 180	        {
 181	            PROFILE_GPU("Copy frame");
 182	            context->SetRenderTarget(output);
 183	            context->Draw(input);
 184	        }
 185	    }
 186	}
