 202	    RenderTargetPool::Release(lightBuffer);
 203	    context->SetRenderTarget(task->GetOutputView());
 204	    context->SetViewportAndScissors(task->GetOutputViewport());
 205	    context->Draw(tempBuffer);
 206	    RenderTargetPool::Release(tempBuffer);
 207	}
