127	bool InitAtmospherePreCompute()
128	{
129	    if (_isReadyForCompute)
130	        return false;
131	    PROFILE_CPU();
132	
133	    // Load shader
134	    if (_shader == nullptr)
135	    {
136	        LOG(Warning, "Failed to load AtmospherePreCompute shader!");
137	        return true;
138	    }
139	    if (_shader->WaitForLoaded())
140	    {
141	        LOG(Warning, "Loading AtmospherePreCompute shader timeout!");
142	        return true;
143	    }
144	    auto shader = _shader->GetShader();
145	    ASSERT(shader->GetCB(0) != nullptr);
146	    CHECK_INVALID_SHADER_PASS_CB_SIZE(shader, 0, Data);
147	    auto device = GPUDevice::Instance;
148	
149	    // Create pipeline stages
150	    _psTransmittance = device->CreatePipelineState();
151	    _psIrradiance1 = device->CreatePipelineState();
152	    _psIrradianceN = device->CreatePipelineState();
153	    _psCopyIrradianceAdd = device->CreatePipelineState();
154	    _psInscatter1_A = device->CreatePipelineState();
155	    _psInscatter1_B = device->CreatePipelineState();
156	    _psCopyInscatter1 = device->CreatePipelineState();
157	    _psInscatterS = device->CreatePipelineState();
158	    _psInscatterN = device->CreatePipelineState();
159	    _psCopyInscatterNAdd = device->CreatePipelineState();
160	    GPUPipelineState::Description psDesc, psDescLayers;
161	    psDesc = GPUPipelineState::Description::DefaultFullscreenTriangle;
162	    psDescLayers = psDesc;
163	    {
164	        psDesc.PS = shader->GetPS("PS_Transmittance");
165	        if (_psTransmittance->Init(psDesc))
166	            return true;
167	    }
168	    {
169	        psDesc.PS = shader->GetPS("PS_Irradiance1");
170	        if (_psIrradiance1->Init(psDesc))
171	            return true;
172	    }
173	    {
174	        psDesc.PS = shader->GetPS("PS_IrradianceN");
175	        if (_psIrradianceN->Init(psDesc))
176	            return true;
177	    }
178	    {
179	        psDescLayers.PS = shader->GetPS("PS_Inscatter1_A");
180	        if (_psInscatter1_A->Init(psDescLayers))
181	            return true;
182	    }
183	    {
184	        psDescLayers.PS = shader->GetPS("PS_Inscatter1_B");
185	        if (_psInscatter1_B->Init(psDescLayers))
186	            return true;
187	    }
188	    {
189	        psDescLayers.PS = shader->GetPS("PS_CopyInscatter1");
190	        if (_psCopyInscatter1->Init(psDescLayers))
191	            return true;
192	    }
193	    {
194	        psDescLayers.PS = shader->GetPS("PS_InscatterS");
195	        if (_psInscatterS->Init(psDescLayers))
196	            return true;
197	    }
198	    {
199	        psDescLayers.PS = shader->GetPS("PS_InscatterN");
200	        if (_psInscatterN->Init(psDescLayers))
201	            return true;
202	    }
203	    psDescLayers.BlendMode = BlendingMode::Add;
204	    psDesc.BlendMode = BlendingMode::Add;
205	    {
206	        psDescLayers.PS = shader->GetPS("PS_CopyInscatterN");
207	        if (_psCopyInscatterNAdd->Init(psDescLayers))
208	            return true;
209	    }
210	    {
211	        psDesc.PS = shader->GetPS("PS_CopyIrradiance1");
212	        if (_psCopyIrradianceAdd->Init(psDesc))
213	            return true;
214	    }
215	
216	    // Init rendering pipeline
217	    _task = New<SceneRenderTask>();
218	    _task->Enabled = false;
219	    _task->IsCustomRendering = true;
220	    _task->Render.Bind(Render);
221	
222	    // Init render targets
223	    if (!AtmosphereTransmittance)
224	    {
225	        AtmosphereTransmittance = device->CreateTexture(TEXT("AtmospherePreCompute.Transmittance"));
226	        auto desc = GPUTextureDescription::New2D(TransmittanceTexWidth, TransmittanceTexHeight, PixelFormat::R16G16B16A16_Float, GPUTextureFlags::ShaderResource | GPUTextureFlags::RenderTarget);
227	        if (AtmosphereTransmittance->Init(desc))
228	            return true;
229	        AtmosphereIrradiance = device->CreateTexture(TEXT("AtmospherePreCompute.Irradiance"));
230	        desc = GPUTextureDescription::New2D(IrradianceTexWidth, IrradianceTexHeight, PixelFormat::R16G16B16A16_Float, GPUTextureFlags::ShaderResource | GPUTextureFlags::RenderTarget);
231	        if (AtmosphereIrradiance->Init(desc))
232	            return true;
233	        AtmosphereInscatter = device->CreateTexture(TEXT("AtmospherePreCompute.Inscatter"));
234	        desc = GPUTextureDescription::New3D(InscatterWidth, InscatterHeight, InscatterDepth, PixelFormat::R16G16B16A16_Float, GPUTextureFlags::ShaderResource | GPUTextureFlags::RenderTarget | GPUTextureFlags::PerSliceViews);
