136	bool InitAtmospherePreCompute()
137	{
138	    if (_isReadyForCompute)
139	        return false;
140	    PROFILE_CPU();
141	
142	    // Load shader
143	    if (_shader == nullptr)
144	    {
145	        LOG(Warning, "Failed to load AtmospherePreCompute shader!");
146	        return true;
147	    }
148	    if (_shader->WaitForLoaded())
149	    {
150	        LOG(Warning, "Loading AtmospherePreCompute shader timeout!");
151	        return true;
152	    }
153	    auto shader = _shader->GetShader();
154	    ASSERT(shader->GetCB(0) != nullptr);
155	    CHECK_INVALID_SHADER_PASS_CB_SIZE(shader, 0, Data);
156	    auto device = GPUDevice::Instance;
157	
158	    // Create pipeline stages
159	    _psTransmittance = device->CreatePipelineState();
160	    _psIrradiance1 = device->CreatePipelineState();
161	    _psIrradianceN = device->CreatePipelineState();
162	    _psCopyIrradianceAdd = device->CreatePipelineState();
163	    _psInscatter1_A = device->CreatePipelineState();
164	    _psInscatter1_B = device->CreatePipelineState();
165	    _psCopyInscatter1 = device->CreatePipelineState();
166	    _psInscatterS = device->CreatePipelineState();
167	    _psInscatterN = device->CreatePipelineState();
168	    _psCopyInscatterNAdd = device->CreatePipelineState();
169	    GPUPipelineState::Description psDesc, psDescLayers;
170	    psDesc = GPUPipelineState::Description::DefaultFullscreenTriangle;
171	    psDescLayers = psDesc;
172	    {
173	        psDesc.PS = shader->GetPS("PS_Transmittance");
174	        if (_psTransmittance->Init(psDesc))
175	            return true;
176	    }
177	    {
178	        psDesc.PS = shader->GetPS("PS_Irradiance1");
179	        if (_psIrradiance1->Init(psDesc))
180	            return true;
181	    }
182	    {
183	        psDesc.PS = shader->GetPS("PS_IrradianceN");
184	        if (_psIrradianceN->Init(psDesc))
185	            return true;
186	    }
187	    {
188	        psDescLayers.PS = shader->GetPS("PS_Inscatter1_A");
189	        if (_psInscatter1_A->Init(psDescLayers))
190	            return true;
191	    }
192	    {
193	        psDescLayers.PS = shader->GetPS("PS_Inscatter1_B");
194	        if (_psInscatter1_B->Init(psDescLayers))
195	            return true;
196	    }
197	    {
198	        psDescLayers.PS = shader->GetPS("PS_CopyInscatter1");
199	        if (_psCopyInscatter1->Init(psDescLayers))
200	            return true;
201	    }
202	    {
203	        psDescLayers.PS = shader->GetPS("PS_InscatterS");
204	        if (_psInscatterS->Init(psDescLayers))
205	            return true;
206	    }
207	    {
208	        psDescLayers.PS = shader->GetPS("PS_InscatterN");
209	        if (_psInscatterN->Init(psDescLayers))
210	            return true;
211	    }
212	    psDescLayers.BlendMode = BlendingMode::Add;
213	    psDesc.BlendMode = BlendingMode::Add;
214	    {
215	        psDescLayers.PS = shader->GetPS("PS_CopyInscatterN");
216	        if (_psCopyInscatterNAdd->Init(psDescLayers))
217	            return true;
218	    }
219	    {
220	        psDesc.PS = shader->GetPS("PS_CopyIrradiance1");
221	        if (_psCopyIrradianceAdd->Init(psDesc))
222	            return true;
223	    }
224	
225	    // Init rendering pipeline
226	    _task = New<SceneRenderTask>();
227	    _task->Enabled = false;
228	    _task->IsCustomRendering = true;
229	    _task->Render.Bind(Render);
230	
231	    // Init render targets
232	    if (!AtmosphereTransmittance)
233	    {
234	        AtmosphereTransmittance = device->CreateTexture(TEXT("AtmospherePreCompute.Transmittance"));
235	        auto desc = GPUTextureDescription::New2D(TransmittanceTexWidth, TransmittanceTexHeight, PixelFormat::R16G16B16A16_Float, GPUTextureFlags::ShaderResource | GPUTextureFlags::RenderTarget);
236	        if (AtmosphereTransmittance->Init(desc))
237	            return true;
238	        AtmosphereIrradiance = device->CreateTexture(TEXT("AtmospherePreCompute.Irradiance"));
239	        desc = GPUTextureDescription::New2D(IrradianceTexWidth, IrradianceTexHeight, PixelFormat::R16G16B16A16_Float, GPUTextureFlags::ShaderResource | GPUTextureFlags::RenderTarget);
240	        if (AtmosphereIrradiance->Init(desc))
241	            return true;
242	        AtmosphereInscatter = device->CreateTexture(TEXT("AtmospherePreCompute.Inscatter"));
243	        desc = GPUTextureDescription::New3D(InscatterWidth, InscatterHeight, InscatterDepth, PixelFormat::R16G16B16A16_Float, GPUTextureFlags::ShaderResource | GPUTextureFlags::RenderTarget | GPUTextureFlags::PerSliceViews);
244	        if (AtmosphereInscatter->Init(desc))
245	            return true;
246	    }
247	
248	    // Mark as ready
249	    _isReadyForCompute = true;
250	    _wasCancelled = false;
251	    return false;
252	}
