226	        _initFailed = _shader == nullptr;
227	        if (_initFailed)
228	            return false;
229	#if COMPILE_WITH_DEV_ENV
230	        _shader->OnReloading.Bind<ProbesRendererService, &ProbesRendererService::OnShaderReloading>(this);
