237	    // Init rendering pipeline
238	    _output = GPUDevice::Instance->CreateTexture(TEXT("ProbesRenderer.Output"));
239	    const int32 probeResolution = _current.GetResolution();
240	    const PixelFormat probeFormat = _current.GetFormat();
241	    _initFailed |= _output->Init(GPUTextureDescription::New2D(probeResolution, probeResolution, probeFormat));
242	    _task = New<SceneRenderTask>();
243	    auto task = _task;
244	    task->Order = -100; // Run before main view rendering (realtime probes will get smaller latency)
245	    task->Enabled = false;
246	    task->IsCustomRendering = true;
247	    task->ActorsSource = ActorsSources::ScenesAndCustomActors;
248	    task->Output = _output;
