 60	// Custom task called after downloading probe texture data to save it.
 61	class DownloadProbeTask : public ThreadPoolTask
 62	{
 63	private:
 64	    GPUTexture* _texture;
 65	    TextureData _data;
 66	    ProbeEntry _entry;
 67	
 68	public:
 69	    DownloadProbeTask(GPUTexture* target, const ProbeEntry& entry)
 70	        : _texture(target)
 71	        , _entry(entry)
 72	    {
 73	    }
 74	
 75	    FORCE_INLINE TextureData& GetData()
 76	    {
 77	        return _data;
 78	    }
 79	
 80	    bool Run() override
 81	    {
 82	        Actor* actor = _entry.Actor.Get();
 83	        if (_entry.Type == ProbeEntry::Types::EnvProbe)
 84	        {
 85	            if (actor)
 86	                ((EnvironmentProbe*)actor)->SetProbeData(_data);
 87	        }
 88	        else if (_entry.Type == ProbeEntry::Types::SkyLight)
 89	        {
 90	            if (actor)
 91	                ((SkyLight*)actor)->SetProbeData(_data);
 92	        }
 93	        else
 94	        {
 95	            return true;
 96	        }
 97	
 98	        ProbesRenderer::OnFinishBake(actor);
 99	        return false;
100	    }
101	};
