253	        ViewFlags::DirectionalLights |
254	        ViewFlags::PointLights |
255	        ViewFlags::SpotLights |
256	        ViewFlags::SkyLights |
257	        ViewFlags::Decals |
258	        ViewFlags::Shadows |
259	        ViewFlags::Sky |
260	        ViewFlags::Fog;
261	    view.Mode = ViewMode::NoPostFx;
262	    view.IsOfflinePass = true;
263	    view.IsSingleFrame = true;
264	    view.StaticFlagsMask = view.StaticFlagsCompare = StaticFlags::ReflectionProbe;
265	    task->IsCameraCut = true;
266	    task->Resize(probeResolution, probeResolution);
267	    task->Render.Bind<ProbesRendererService, &ProbesRendererService::OnRender>(this);
268	    task->SetupRender.Bind<ProbesRendererService, &ProbesRendererService::OnSetupRender>(this);
269	
270	    // Init render targets
271	    _probe = GPUDevice::Instance->CreateTexture(TEXT("ProbesRenderer.Probe"));
272	    _initFailed |= _probe->Init(GPUTextureDescription::NewCube(probeResolution, probeFormat, GPUTextureFlags::ShaderResource | GPUTextureFlags::RenderTarget | GPUTextureFlags::PerMipViews, 0));
273	    _tmpFace = GPUDevice::Instance->CreateTexture(TEXT("ProbesRenderer.TmpFace"));
