643	## 示例：完整渲染管线
644	
645	```cpp
646	void BuildRenderGraph(RenderGraph& graph, RenderContext& renderContext)
647	{
648	    // 1. GBuffer Pass
649	    auto gbuffer = graph.AddPass<GBufferPass>();
650	    
651	    // 2. Shadow Pass
652	    auto shadows = graph.AddPass<ShadowsPass>();
653	    
654	    // 3. Lighting Pass
655	    auto lighting = graph.AddPass<LightPass>();
656	    lighting->SetGBufferInput(gbuffer->GetGBuffer());
657	    lighting->SetShadowInput(shadows->GetShadowMap());
658	    
659	    // 4. SSAO Pass (可选)
660	    if (renderContext.View.Flags & ViewFlags::AO)
661	    {
662	        auto ssao = graph.AddPass<SSAOPass>();
663	        ssao->SetDepthInput(gbuffer->GetDepth());
664	        lighting->SetAOInput(ssao->GetOutput());
665	    }
666	    
667	    // 5. Post Processing
668	    auto postProcess = graph.AddPass<PostProcessPass>();
669	    postProcess->SetInput(lighting->GetOutput());
670	    
671	    // 6. TAA (可选)
672	    if (renderContext.View.Flags & ViewFlags::TAA)
673	    {
674	        auto taa = graph.AddPass<TAAPass>();
675	        taa->SetInput(postProcess->GetOutput());
676	        taa->SetMotionVectors(gbuffer->GetMotionVectors());
677	    }
678	    
679	    // 编译并执行
680	    graph.Compile();
681	    graph.Execute(renderContext.GPUContext);
682	}
683	```
